guides.example:
lock counters guards Counter;

fn bump(c: &mut Counter) -> ()
  ! owns(counters)
{
  holding counters { c.n = c.n + 1; }
}

fn ack(s: &mut Shoot, cpu: u64) -> ()
  ! write(shootdown)
  interleaves {
    asks final(s).epoch == s.epoch
    promises final(s).acked == s.acked | (1 << cpu)
  }

protocol PageRequest {
  User     { op: u32, count: u64 },
  Provider { status: u32, base: u64 },
  end
}
